SELECT grouped.* FROM (
    SELECT d.id AS document_id, d.title, count(*) AS publication_count,
        max(p.position) AS position, max(p.published_at) AS latest_published_at
     JOIN kb_knowledge_delivery kd ON kd.id = #{digestId}
    WHERE  GROUP BY d.id, d.title
) grouped WHERE TRUE
AND (grouped.position, grouped.document_id) < (#{beforePosition}, #{beforeDocumentId})
